from solution import positive_count


def test_issue_example_from_description():
    """Example ratio of positive numbers in 13-element array is 0.54."""
    assert positive_count([0, 1, 2, -1, -5, 6, 0, -3, -2, 3, 4, 6, 8]) == 0.54  # 7/13=0.538... -> 0.54


def test_issue_all_positive():
    """Ratio of positive numbers is 1.0 when all are positive."""
    assert positive_count([1, 2, 3]) == 1.0  # 3/3=1.0


def test_issue_all_negative():
    """Ratio of positive numbers is 0.0 when none are positive."""
    assert positive_count([-1, -2, -3]) == 0.0  # 0/3=0.0


def test_issue_all_zeros_not_positive():
    """Ratio of positive numbers is 0.0 when all are zero."""
    assert positive_count([0, 0, 0]) == 0.0  # 0/3=0.0


def test_issue_zero_not_counted_as_positive():
    """Ratio counts only strictly positive numbers so zero is excluded."""
    assert positive_count([0, 1]) == 0.5  # 1/2=0.5


def test_issue_single_positive():
    """Ratio of positive numbers in single-element positive array is 1.0."""
    assert positive_count([7]) == 1.0  # 1/1=1.0


def test_issue_single_negative():
    """Ratio of positive numbers in single-element negative array is 0.0."""
    assert positive_count([-7]) == 0.0  # 0/1=0.0


def test_issue_single_zero():
    """Ratio of positive numbers in single-element zero array is 0.0."""
    assert positive_count([0]) == 0.0  # 0/1=0.0


def test_issue_even_half_split():
    """Ratio of positive numbers with half positive is 0.5."""
    assert positive_count([1, -1, 2, -2]) == 0.5  # 2/4=0.5


def test_issue_three_quarters_positive():
    """Ratio of positive numbers with three of four positive is 0.75."""
    assert positive_count([1, 2, 3, -1]) == 0.75  # 3/4=0.75


def test_contract_one_third_rounds_to_two_decimals():
    """Ratio follows example two-decimal rounding so 1 of 3 is 0.33."""
    assert positive_count([1, -1, -1]) == 0.33  # 1/3=0.333... -> 0.33


def test_contract_two_thirds_rounds_to_two_decimals():
    """Ratio follows example two-decimal rounding so 2 of 3 is 0.67."""
    assert positive_count([1, 1, -1]) == 0.67  # 2/3=0.666... -> 0.67
